<script setup lang="ts">
const games=ref<any[]>([]),game=ref<any>(null),events=ref<any[]>([]),world=ref<any[]>([]),ledger=ref<any[]>([])
const tab=ref('overview'),busy=ref(false),error=ref(''),name=ref('Vanguard Security'),seed=ref('asterra-01'),batch=ref(1),stop=ref(true),result=ref<any>(null),selectedCountry=ref(''),showCreate=ref(false)
useHead(()=>({title:game.value?game.value.name+' · OPERATORS — PMC Command':'OPERATORS — PMC Command'}))
const deletingCompany=ref<any>(null),deleteName=ref('')
const registrationCountryId=ref('valdoria'),registrationCountries=ref<any[]>([])
const difficulty=ref('normal'),difficultyOptions=ref<any[]>([])
const selectedDifficulty=computed(()=>difficultyOptions.value.find(p=>p.id===difficulty.value))
const nav=[['overview','◈','Visão geral'],['world','◎','Mundo'],['operators','♙','Operadores'],['contracts','▤','Contratos'],['operations','⌁','Operações'],['finance','▥','Finanças']]
const currency=(value:number,precise=false)=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'USD',minimumFractionDigits:precise?2:0,maximumFractionDigits:precise?2:0}).format(value/100)
const date=computed(()=>game.value?new Date(game.value.date).toLocaleString('pt-BR',{timeZone:'UTC',day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'}):'')
const command=ref<any>(null),loadingCampaign=ref(true),dockHeight=ref(160),cancelRequest=ref<any>(null)
const country=computed(()=>world.value.find(c=>c.id===selectedCountry.value)||world.value[0])
const contractRegion=ref('')
const worldContext=useState<Record<string,string>>('world-region',()=>({}))
const worldFocus=useState<Record<string,string>>('world-event',()=>({}))
function openWorld(target:{regionId:string;eventId:string}){worldContext.value={...worldContext.value,[game.value.id]:target.regionId};worldFocus.value={...worldFocus.value,[game.value.id]:target.eventId};tab.value='world'}
const pendingAdvance=ref<any>(null)
const pendingCreation=ref<any>(null)
const personnelSummary=ref<any>({}),personnelWorking=ref(false),operationsSummary=ref<any>({missions:[],decisions:[]})
const entryName=(type:string)=>(({intelligence_analysis:'Análise de inteligência',equipment_purchase:'Compra de kits',equipment_maintenance:'Reparo de kit',equipment_resupply:'Reposição de suprimentos',headquarters_upgrade:'Melhoria da sede',headquarters_maintenance:'Manutenção da sede',operator_training:'Treinamento',operator_treatment:'Tratamento',initial_capital:'Capital inicial',signing_bonus:'Bônus de assinatura',salary_payment:'Pagamento salarial',mission_mobilization:'Mobilização',mission_advance:'Adiantamento de missão',mission_completion:'Acerto de missão',advance_refund:'Devolução de adiantamento'} as Record<string,string>)[type]||type)
async function api(path:string,options:any={}){return await $fetch<any>('/api/v1'+path,options)}
async function load(){const [list,profiles,countries]=await Promise.all([api('/games'),api('/difficulties'),api('/registration-countries')]);games.value=list;difficultyOptions.value=profiles;registrationCountries.value=countries}
async function select(id:string){const entering=!game.value;busy.value=true;error.value='';try{await api('/games/'+id+'/logistics');await api('/games/'+id+'/intelligence');const selected=await api('/games/'+id);const [nextEvents,nextWorld,nextLedger,nextPersonnel,nextOperations,nextCommand]=await Promise.all([api(`/games/${id}/timeline`),api(`/games/${id}/world/countries`),api(`/games/${id}/finances/ledger`),api(`/games/${id}/finances/summary`),api(`/games/${id}/operations`),api(`/games/${id}/command-center`)]);game.value=selected;events.value=nextEvents;world.value=nextWorld;ledger.value=nextLedger;personnelSummary.value=nextPersonnel;operationsSummary.value=nextOperations;command.value=nextCommand;localStorage.setItem('operators-game',id);result.value=command.value?.latestAdvance??null;pendingAdvance.value=result.value?.status==='processing'?result.value.command:null;if(entering&&typeof window!=='undefined'){await nextTick();window.scrollTo({top:0,left:0,behavior:'instant'})}return true}catch(e:any){error.value=e.data?.message||'Não foi possível abrir a partida.';return false}finally{busy.value=false}}
function requestDelete(company:any){deletingCompany.value=company;deleteName.value='';error.value=''}
async function removeCompany(){
 if(busy.value||!deletingCompany.value||deleteName.value!==deletingCompany.value.name)return;
 busy.value=true;error.value='';
 try{await api('/games/'+deletingCompany.value.id,{method:'DELETE',body:{confirmationName:deleteName.value,expectedVersion:deletingCompany.value.stateVersion}});deletingCompany.value=null;await load()}
 catch(e:any){if(e.status===404){deletingCompany.value=null;await load()}else error.value=e.data?.message||'Não foi possível excluir. Atualize a lista para verificar e tente novamente.'}
 finally{busy.value=false}
}
async function create(){
 if(busy.value||personnelWorking.value)return;
 busy.value=true;error.value='';
 try{
  const command=pendingCreation.value||{requestId:crypto.randomUUID(),name:name.value,seed:seed.value,difficulty:difficulty.value,registrationCountryId:registrationCountryId.value};
  pendingCreation.value=command;
  const created=await api('/games',{method:'POST',body:command});
  await load();
  if(!await select(created.id))return;
  pendingCreation.value=null;showCreate.value=false;
 }catch(e:any){
  if(e.status>=400&&e.status<500)pendingCreation.value=null;
  error.value=e.data?.message||'Falha de conexão. Tente novamente para recuperar a mesma criação.';
 }finally{busy.value=false}
}
async function advance(){if(!game.value||busy.value||personnelWorking.value)return;busy.value=true;error.value='';try{const command=pendingAdvance.value||{requestId:crypto.randomUUID(),expectedVersion:game.value.stateVersion,turns:Number(batch.value),stopOnImportant:stop.value};pendingAdvance.value=command;const r=await api(`/games/${game.value.id}/advance`,{method:'POST',body:command});const id=game.value.id;result.value=r;if(!await select(id))return;result.value=r;pendingAdvance.value=null}catch(e:any){error.value=e.data?.message||'Falha de conexão. Tente novamente para consultar a mesma requisição.';if(e.status>=400&&e.status<500){pendingAdvance.value=null;await select(game.value.id);error.value=e.data?.message||'Revise as ordens antes de avançar.'}}finally{busy.value=false}}
async function cancelOrder(orderId:string){
 if(busy.value||personnelWorking.value)return;busy.value=true;error.value='';
 const request=cancelRequest.value||{orderId,body:{requestId:crypto.randomUUID(),expectedVersion:game.value.stateVersion}};cancelRequest.value=request;
 try{await api(`/games/${game.value.id}/orders/${request.orderId}/cancel`,{method:'POST',body:request.body});cancelRequest.value=null;await select(game.value.id)}catch(e:any){if(e.status>=400&&e.status<500){cancelRequest.value=null;await select(game.value.id)}error.value=e.data?.message||'Falha ao remover a ordem. Repita para recuperar a mesma solicitação.'}finally{busy.value=false}
}
async function resume(){busy.value=true;error.value='';try{const r=await api(`/games/${game.value.id}/advances/${result.value.requestId}/resume`,{method:'POST',body:{expectedVersion:game.value.stateVersion}});result.value=r;if(!await select(game.value.id))return;result.value=r}catch(e:any){error.value=e.data?.message||'Não foi possível retomar.'}finally{busy.value=false}}
async function home(){if(busy.value||personnelWorking.value)return;busy.value=true;error.value='';try{await load();game.value=null;tab.value='overview';showCreate.value=false;contractRegion.value='';if(typeof window!=='undefined'){await nextTick();window.scrollTo({top:0,left:0,behavior:'instant'})}}catch{error.value='Não foi possível carregar as companhias. Tente novamente.'}finally{busy.value=false}}
onMounted(async()=>{try{await load()}catch{error.value='Não foi possível conectar. Atualize a página para tentar novamente.'}finally{loadingCampaign.value=false}})
</script>
<template>
<div v-if="!game" class="campaign-home">
 <header class="home-header"><a class="home-logo" href="/">OPERATORS<span>PMC COMMAND</span></a><span class="home-private"><i class="live-dot"></i> ACESSO PRIVADO</span></header>
 <main class="home-content"><section class="home-intro"><div><div class="eyebrow">SEU CENTRO DE OPERAÇÕES</div><h1>Escolha sua companhia.</h1><p>Retome uma campanha em andamento ou estabeleça um novo comando em Asterra.</p></div><button v-if="games.length" class="primary" :disabled="busy||!!pendingCreation" @click="showCreate=!showCreate">{{showCreate?'Fechar criação':'Criar companhia'}}</button></section>
 <div v-if="error" class="error" role="alert">{{error}} <button v-if="!pendingCreation" class="secondary" :disabled="busy" @click="home">Tentar novamente</button></div>
 <section v-if="loadingCampaign" class="panel" role="status">Carregando companhias…</section>
 <section v-else-if="showCreate||!games.length||pendingCreation" class="panel create home-create"><div><span class="eyebrow">NOVO COMANDO</span><h2>Estabeleça sua companhia.</h2><p>Escolha o nome que representará seu comando. Cada companhia tem sua própria campanha e progresso.</p></div><form @submit.prevent="create"><label>Nome da companhia<input v-model="name" :disabled="busy||!!pendingCreation" required minlength="2" maxlength="60" placeholder="Nome da sua companhia"></label><label>País de registro<select v-model="registrationCountryId" :disabled="busy||!!pendingCreation" required><option v-for="c in registrationCountries" :key="c.id" :value="c.id">{{c.name}}</option></select><small>Escolha permanente. Sem efeitos nas regras do MVP.</small></label><label>Semente da campanha<input v-model="seed" :disabled="busy||!!pendingCreation" required maxlength="100"></label><fieldset class="difficulty-fieldset" :disabled="busy||!!pendingCreation"><legend>Dificuldade da campanha</legend><div class="difficulty-options"><label v-for="profile in difficultyOptions" :key="profile.id" :class="['difficulty-choice',{selected:difficulty===profile.id}]"><input v-model="difficulty" type="radio" name="difficulty" :value="profile.id"><span><strong>{{profile.label}}</strong><small>{{profile.description}}</small></span></label></div><p class="difficulty-permanent">A dificuldade não poderá ser alterada nesta campanha.</p><details v-if="selectedDifficulty" class="difficulty-details"><summary>Ver modificadores · {{selectedDifficulty.label}}</summary><dl><div><dt>Eventos negativos</dt><dd>×{{selectedDifficulty.negativeEvents}}</dd></div><div><dt>Oportunidades favoráveis</dt><dd>×{{selectedDifficulty.positiveEvents}}</dd></div><div><dt>Complicações em missão</dt><dd>×{{selectedDifficulty.missionComplications}}</dd></div><div><dt>Frequência dos rivais</dt><dd>×{{selectedDifficulty.rivalInterest}}</dd></div><div><dt>Remuneração de novos contratos</dt><dd>×{{selectedDifficulty.contractReward}}</dd></div></dl><p>Aplicados sobre as regras-base, respeitando o contexto. Preços, salários, atributos e prazos são iguais nos três níveis.</p></details></fieldset><button class="primary" :disabled="busy">{{busy?'Criando companhia…':pendingCreation?'Repetir criação':'Criar companhia →'}}</button></form></section>
 <section v-if="!loadingCampaign&&games.length" class="company-list-section"><div class="home-section-heading"><h2>Campanhas em andamento</h2><span>{{games.length}} {{games.length===1?'companhia':'companhias'}}</span></div><div class="company-grid"><article v-for="g in games" :key="g.id" class="company-card"><div class="company-card-top"><span class="eyebrow">COMPANHIA INDEPENDENTE</span><span class="tag">{{g.status==='financial_crisis'?'Atenção financeira':'Em andamento'}}</span></div><h3>{{g.name}}</h3><p>País de registro: {{g.registrationCountryName||'País não informado'}}</p><p class="company-difficulty">{{g.difficultyLabel||'Normal'}} · permanente</p><p class="company-progress">Turno {{g.currentTurn}} · Semana {{Math.floor(g.currentTurn/28)+1}}</p><div class="company-metrics"><div><span>CAIXA</span><strong>{{currency(g.cashCents)}}</strong></div><div><span>REPUTAÇÃO</span><strong>{{g.reputation}}<small> / 100</small></strong></div></div><button class="secondary" :disabled="busy||!!pendingCreation" @click="tab='overview';select(g.id)">{{busy?'Abrindo companhia…':'Entrar na companhia →'}}</button><button class="company-delete" :aria-label="'Excluir companhia '+g.name" :disabled="busy||!!pendingCreation" @click="requestDelete(g)">Excluir companhia</button></article></div></section>
 <section v-if="deletingCompany" class="delete-company-backdrop"><form class="panel delete-company-dialog" role="dialog" aria-modal="true" aria-labelledby="delete-company-title" @submit.prevent="removeCompany"><h2 id="delete-company-title">Excluir companhia?</h2><p>Você excluirá <strong>{{deletingCompany.name}}</strong> e todo o progresso, operadores, missões e histórico desta campanha. Esta ação é imediata e não pode ser desfeita.</p><label>Digite o nome da companhia para confirmar<input v-model="deleteName" :disabled="busy" autocomplete="off" autofocus></label><p v-if="error" class="error" role="alert">{{error}}</p><div class="heading-actions"><button type="button" class="secondary" :disabled="busy" @click="deletingCompany=null">Cancelar</button><button type="submit" class="danger" :disabled="busy||deleteName!==deletingCompany.name">{{busy?'Excluindo…':'Excluir definitivamente'}}</button></div></form></section>
 <footer><span>OPERATORS <b> / </b> PMC COMMAND</span><span>SEU COMANDO. SUA HISTÓRIA.</span></footer></main>
</div>
<div v-else class="shell planned-shell" :style="{ '--turn-dock-height':dockHeight+'px' }">
 <aside><button class="brand company-brand" :disabled="busy||personnelWorking" @click="home" aria-label="Voltar às companhias"><strong>{{game.name}}</strong><span>OPERATORS · PMC COMMAND</span></button><button class="company-return" :disabled="busy||personnelWorking" @click="home">← Companhias</button><div class="workspace-label">CENTRO DE COMANDO</div><nav><button v-for="item in nav" :key="item[0]" :class="{active:tab===item[0]}" :disabled="busy||personnelWorking" @click="tab=item[0]"><span>{{item[1]}}</span>{{item[2]}}</button></nav><div class="aside-bottom"><span class="live-dot"></span> ACESSO PRIVADO<div>Comando · v0.10.0</div></div></aside>
 <main><header class="account-bar"><div class="account-identity"><strong>{{game.name}}</strong><small>{{game.difficultyLabel||'Normal'}} · Turno {{game.currentTurn}} · {{date}}</small></div><div class="account-balance"><span>SALDO DA CONTA</span><strong>{{currency(game.cashCents,true)}}</strong></div><div v-if="command?.pendingOrders?.length" class="planned-balance"><span>Despesas planejadas <b>{{currency(command.plannedExpensesCents,true)}}</b></span><span v-if="command.plannedIncomeCents">Receitas líquidas previstas <b>{{currency(command.plannedIncomeCents,true)}}</b></span><span>Após confirmar <b>{{currency(command.projectedCashCents,true)}}</b></span></div></header>
 <div class="content"><div class="page-heading"><div><div class="eyebrow">OPERAÇÃO INDEPENDENTE</div><h1>{{tab==='overview'?'Painel de comando':tab==='infrastructure'?'Sede e logística':nav.find(n=>n[0]===tab)?.[2]}}</h1><p>Decisões estratégicas. Consequências persistentes.</p></div><div class="heading-actions"><button v-if="game" class="secondary" :disabled="busy||personnelWorking" @click="tab='infrastructure'">Sede e logística</button></div></div>
 <div v-if="error" role="alert" class="error">{{error}}</div><p v-if="personnelWorking&&!busy" class="batch-result" role="status">Uma ordem está sendo salva na fila. Conclua ou repita a solicitação nesta tela antes de navegar ou avançar.</p>
 <template v-if="game">
 <div class="campaign-bar company-status"><span><i class="live-dot"></i> {{game.status==='financial_crisis'?'ATENÇÃO FINANCEIRA':'COMPANHIA ATIVA'}}</span><span>{{game.difficultyLabel||'Normal'}} · permanente</span><span>Registro: {{game.registrationCountryName||'País não informado'}}</span><span>ASTERRA · TURNO {{game.currentTurn}}</span></div>
 <template v-if="tab==='overview'">
 <section v-if="command?.alerts?.length" class="panel command-alerts"><div class="panel-heading"><h2>Atenção do comandante</h2><span class="tag">{{command.alerts.length}} PENDÊNCIAS</span></div><article v-for="a in command.alerts" :key="a.id" class="command-alert" :class="a.severity"><div><h3>{{a.title}}</h3><p>{{a.description}}</p></div><button class="secondary" :disabled="busy||personnelWorking" @click="tab=a.tab">Resolver →</button></article></section>
 <div class="stats"><section class="stat"><span>CAIXA DISPONÍVEL</span><strong>{{currency(game.cashCents)}}</strong><small>{{personnelSummary.employed||0}} vínculos ativos</small></section><section class="stat"><span>REPUTAÇÃO GLOBAL</span><strong>{{game.reputation}}<em>/ 100</em></strong><small>Resultados e relações da campanha</small></section><section class="stat"><span>TURNO ATUAL</span><strong>{{String(game.currentTurn).padStart(3,'0')}}</strong><small>Semana {{Math.floor(game.currentTurn/28)+1}} · {{game.currentTurn*6}} horas decorridas</small></section><section class="stat"><span>QUADRO DE OPERADORES</span><strong>{{personnelSummary.employed||0}}<em> / {{personnelSummary.capacity||12}}</em></strong><small>Operadores com vínculo ativo</small></section></div>

 <div v-if="result" class="batch-result" role="status"><strong>{{result.reason==='critical_decision'?'Decisão do comandante necessária':result.status==='completed'?'Avanço concluído':result.status==='failed'?'Lote interrompido por falha':result.status==='processing'?'Avanço aguardando conclusão':'Evento importante'}}</strong> · {{result.processedTurns}} de {{result.requestedTurns}} turnos confirmados. Turno atual: {{result.currentTurn}}. <span v-if="command?.latestAdvance?.requestId===result.requestId">Movimentação no avanço: {{currency(command.latestAdvance.cashMovementCents,true)}} · {{command.latestAdvance.eventCount}} ocorrências.</span><button v-if="result.status==='failed'" @click="resume" :disabled="busy">Retomar restantes</button></div>
 <section v-if="command?.latestAdvance" class="panel batch-details"><details><summary>Resumo do último avanço · T{{command.latestAdvance.startTurn}} → T{{command.latestAdvance.endTurn}}</summary><p>Receitas {{currency(command.latestAdvance.receiptsCents,true)}} · despesas {{currency(command.latestAdvance.expensesCents,true)}}. Inclui ordens confirmadas no primeiro turno e movimentações automáticas dos turnos processados.</p><ul><li v-for="e in command.latestAdvance.events" :key="e.type+e.title">{{e.title}} <strong>× {{e.count}}</strong></li></ul><p v-if="!command.latestAdvance.events.length">Nenhuma ocorrência adicional nos turnos confirmados.</p></details></section>
 <div class="command-grid"><section v-if="command?.steps?.some((s:any)=>!s.done)" class="panel"><h2>Preparar a companhia</h2><button v-for="s in command.steps" :key="s.id" class="setup-step" :disabled="busy||personnelWorking" @click="tab=s.tab"><span>{{s.done?'✓':'○'}}</span>{{s.title}}<small>{{s.done?'Concluído':'Abrir →'}}</small></button></section><section v-if="command?.agenda?.length" class="panel"><h2>Próximos prazos</h2><button v-for="a in command.agenda.slice(0,8)" :key="a.id" class="agenda-item" :disabled="busy||personnelWorking" @click="tab=a.tab"><span>{{a.title}}</span><strong>T{{a.dueTurn}}</strong></button><p>Prazos avançam somente sob seu comando. Decisões vencidas aplicam a política automática.</p></section></div>
 <div class="dashboard-grid"><section class="panel"><div class="panel-heading"><h2>Registro de comando</h2><span class="tag">HISTÓRICO</span></div><div v-if="!events.length" class="empty"><div class="empty-icon">⌁</div><h3>Aguardando seu primeiro comando</h3><p>Avance o tempo para registrar os primeiros eventos da campanha.</p></div><div v-for="event in events.slice(0,8)" :key="`${event.turn}-${event.sequence}`" class="event"><span class="event-marker" :class="{important:event.important}"></span><div><div class="event-title">{{event.title}}<small>T{{String(event.turn).padStart(3,'0')}}</small></div><p>{{event.description}}</p></div></div></section><div class="right-stack"><section class="panel briefing"><div class="eyebrow">SITUAÇÃO ATUAL</div><h2>Gestão da companhia.</h2><p>Campanha persistente, pessoal e folha salarial integrados ao relógio.</p><div class="brief-line"><span>Persistência</span><strong>Salvamento online</strong></div><div class="brief-line"><span>Avanço</span><strong>1 a 28 turnos</strong></div><div class="brief-line"><span>Custo semanal atual</span><strong>{{currency(command?.finance?.weeklyTotalCents||0)}}</strong></div><p v-if="command?.finance?.runwayWeeks!==null">Caixa cobre cerca de {{command?.finance?.runwayWeeks??0}} semanas das despesas atuais, descontadas dívidas. Estimativa sem novas receitas ou gastos pontuais.</p></section><section class="panel note"><span class="eyebrow">ESCOPO DESTA VERSÃO</span><p>Mundo causal, pessoal, missões, kits, sede e inteligência progressiva disponíveis. Consulte alertas, prazos e resumos de avanço para coordenar a campanha.</p></section></div></div>
 </template>
 <WorldPanel v-else-if="tab==='world'" :game="game" @open-contracts="contractRegion=$event;tab='contracts'" @changed="select(game.id)" @processing="personnelWorking=$event" />
 <LogisticsPanel v-else-if="tab==='infrastructure'" :game="game" @changed="select(game.id)" @processing="personnelWorking=$event" />
 <PersonnelPanel v-else-if="tab==='operators'" :game="game" @changed="select(game.id)" @processing="personnelWorking=$event" />
 <OperationsPanel v-else-if="['contracts','operations'].includes(tab)" :game="game" :mode="tab" :region-id="contractRegion" @clear-region="contractRegion=''" @open-world="openWorld($event)" @changed="select(game.id)" @processing="personnelWorking=$event" />
 <template v-else-if="tab==='finance'"><div class="stats finance-stats"><section class="stat"><span>SALDO EM CAIXA</span><strong>{{currency(game.cashCents)}}</strong><small>Valores fictícios em USD</small></section><section class="stat"><span>DESPESA SEMANAL</span><strong>{{currency(command?.finance?.weeklyTotalCents||0)}}</strong><small>Salários {{currency(command?.finance?.weeklySalariesCents||0)}} + sede {{currency(command?.finance?.weeklyInfrastructureCents||0)}}</small></section><section v-if="command?.finance?.totalArrearsCents" class="stat"><span>DÍVIDA TOTAL</span><strong>{{currency(command.finance.totalArrearsCents)}}</strong><small>Quitação automática quando houver caixa suficiente</small></section></div><section class="panel"><div class="panel-heading"><h2>Livro-razão</h2><span class="tag">AUDITÁVEL</span></div><table><thead><tr><th>TURNO</th><th>LANÇAMENTO</th><th>VALOR</th></tr></thead><tbody><tr v-for="entry in ledger" :key="entry.sourceId"><td data-label="Turno">{{entry.turn}}</td><td data-label="Lançamento">{{entryName(entry.entryType)}}</td><td data-label="Valor" :class="entry.amountCents<0?'debit':'credit'">{{currency(entry.amountCents,true)}}</td></tr></tbody></table></section></template>
 <section v-else class="panel unavailable"><div class="empty-icon">◇</div><span class="eyebrow">MÓDULO EM DESENVOLVIMENTO</span><h2>{{tab==='infrastructure'?'Sede e logística':nav.find(n=>n[0]===tab)?.[2]}}</h2><p>{{tab==='operators'?'O próximo incremento adicionará recrutamento, fichas e equipes permanentes.':tab==='contracts'?'O catálogo e o planejamento serão implementados após operadores e equipes.':'As operações autônomas dependem do planejamento e do motor de missões.'}}</p><button class="secondary" @click="tab='overview'">Voltar ao comando</button></section>
 </template>
 <footer><span>OPERATORS <b> / </b> PMC COMMAND</span><span>COMANDO · 0.10.0</span></footer></div>
 </main>
 <TurnDock :game="game" :command="command" :busy="busy" :locked="personnelWorking" :turns="batch" :stop="stop" :pending="!!pendingAdvance" :result="result" :error="error" @update:turns="batch=$event" @update:stop="stop=$event" @height="dockHeight=$event" @advance="advance" @resume="resume" @cancel="cancelOrder" @navigate="tab=$event" />
</div>
</template>
